// Port of anstyle-parse =0.2.7 `src/state/codegen.rs` (`#[cfg(test)]`).
//
// PORT: upstream's `table` test renders the table built by `generate_state_changes!` (from the
// `vte_generate_state_changes` proc-macro crate) with `generate_table`, runs `rustfmt` over it
// and snapshot-compares it with `table.rs`. Here:
// - `state_changes()` is the macro's expansion written as a function: start from an all-zero
//   `[[u8; 256]; 16]`, and for every `<from> { <bytes> => (<to>, <action>) }` entry store
//   `pack(to, action)` at `[from][byte]` (entries in source order).
// - The snapshot is `table.rs` reconstructed from `table.ts`, whose rows/comments are a verbatim
//   transcription; `rustfmt` leaves the `#[rustfmt::skip]` table untouched, so it is skipped.
//   (When the port was written, `generate_table` output was also checked byte-for-byte against
//   the crate's `table.rs`.)
import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { unwrap_result } from "../../../std/result.ts";
import { pack, unpack, State, State_discriminant, type Action, type State as StateT } from "./definitions.ts";
import { STATE_CHANGES as TABLE } from "./table.ts";

// crate: anstyle-parse-0.2.7/src/state/codegen.rs:7 table
test("table", () => {
  const content = generate_table();

  expect(STATE_CHANGES.map((r) => Array.from(r))).toEqual(TABLE.map((r) => Array.from(r)));
  expect(content).toBe(table_rs_from_table_ts());
});

// crate: anstyle-parse-0.2.7/src/state/codegen.rs:17 generate_table
export function generate_table(): string {
  let file = "";
  file += `// This file is @generated by ${"crates/anstyle-parse/src/state/codegen.rs".replaceAll("\\", "/")}\n`;
  file += "\n";
  file += `${"#[rustfmt::skip]\npub(crate) const STATE_CHANGES: [[u8; 256]; 16] = ["}\n`;

  STATE_CHANGES.forEach((entries, state) => {
    file += `    // ${unwrap_result(State.try_from(state))}\n`;
    file += "    [";
    let last_entry: number | undefined = undefined;
    for (const packed of entries) {
      const [next_state, action] = unpack(packed);
      if (last_entry !== packed) {
        file += "\n";
        file += `        // ${next_state} ${action}\n`;
        file += "        ";
      }
      file += `0x${packed.toString(16).padStart(2, "0")}, `;
      last_entry = packed;
    }
    file += "\n";
    file += "    ],\n";
  });

  file += "];\n";
  return file;
}

/// This is the state change table. It's indexed first by current state and then by the next
/// character in the pty stream.
const STATE_CHANGES: readonly Uint8Array[] = state_changes();

type Entry = [lo: number, hi: number, to: StateT, action: Action];

/** `generate_state_changes!(state_changes, { ... })` */
function state_changes(): Uint8Array[] {
  const spec: [StateT, Entry[]][] = [
    ["Anywhere", [
      [0x18, 0x18, "Ground", "Execute"],
      [0x1a, 0x1a, "Ground", "Execute"],
      [0x1b, 0x1b, "Escape", "Nop"],
    ]],

    ["Ground", [
      [0x00, 0x17, "Anywhere", "Execute"],
      [0x19, 0x19, "Anywhere", "Execute"],
      [0x1c, 0x1f, "Anywhere", "Execute"],
      [0x20, 0x7f, "Anywhere", "Print"],
      [0x80, 0x8f, "Anywhere", "Execute"],
      [0x91, 0x9a, "Anywhere", "Execute"],
      [0x9c, 0x9c, "Anywhere", "Execute"],
      // Beginning of UTF-8 2 byte sequence
      [0xc2, 0xdf, "Utf8", "BeginUtf8"],
      // Beginning of UTF-8 3 byte sequence
      [0xe0, 0xef, "Utf8", "BeginUtf8"],
      // Beginning of UTF-8 4 byte sequence
      [0xf0, 0xf4, "Utf8", "BeginUtf8"],
    ]],

    ["Escape", [
      [0x00, 0x17, "Anywhere", "Execute"],
      [0x19, 0x19, "Anywhere", "Execute"],
      [0x1c, 0x1f, "Anywhere", "Execute"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x20, 0x2f, "EscapeIntermediate", "Collect"],
      [0x30, 0x4f, "Ground", "EscDispatch"],
      [0x51, 0x57, "Ground", "EscDispatch"],
      [0x59, 0x59, "Ground", "EscDispatch"],
      [0x5a, 0x5a, "Ground", "EscDispatch"],
      [0x5c, 0x5c, "Ground", "EscDispatch"],
      [0x60, 0x7e, "Ground", "EscDispatch"],
      [0x5b, 0x5b, "CsiEntry", "Nop"],
      [0x5d, 0x5d, "OscString", "Nop"],
      [0x50, 0x50, "DcsEntry", "Nop"],
      [0x58, 0x58, "SosPmApcString", "Nop"],
      [0x5e, 0x5e, "SosPmApcString", "Nop"],
      [0x5f, 0x5f, "SosPmApcString", "Nop"],
    ]],

    ["EscapeIntermediate", [
      [0x00, 0x17, "Anywhere", "Execute"],
      [0x19, 0x19, "Anywhere", "Execute"],
      [0x1c, 0x1f, "Anywhere", "Execute"],
      [0x20, 0x2f, "Anywhere", "Collect"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x30, 0x7e, "Ground", "EscDispatch"],
    ]],

    ["CsiEntry", [
      [0x00, 0x17, "Anywhere", "Execute"],
      [0x19, 0x19, "Anywhere", "Execute"],
      [0x1c, 0x1f, "Anywhere", "Execute"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x20, 0x2f, "CsiIntermediate", "Collect"],
      [0x30, 0x39, "CsiParam", "Param"],
      [0x3a, 0x3b, "CsiParam", "Param"],
      [0x3c, 0x3f, "CsiParam", "Collect"],
      [0x40, 0x7e, "Ground", "CsiDispatch"],
    ]],

    ["CsiIgnore", [
      [0x00, 0x17, "Anywhere", "Execute"],
      [0x19, 0x19, "Anywhere", "Execute"],
      [0x1c, 0x1f, "Anywhere", "Execute"],
      [0x20, 0x3f, "Anywhere", "Ignore"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x40, 0x7e, "Ground", "Nop"],
    ]],

    ["CsiParam", [
      [0x00, 0x17, "Anywhere", "Execute"],
      [0x19, 0x19, "Anywhere", "Execute"],
      [0x1c, 0x1f, "Anywhere", "Execute"],
      [0x30, 0x39, "Anywhere", "Param"],
      [0x3a, 0x3b, "Anywhere", "Param"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x3c, 0x3f, "CsiIgnore", "Nop"],
      [0x20, 0x2f, "CsiIntermediate", "Collect"],
      [0x40, 0x7e, "Ground", "CsiDispatch"],
    ]],

    ["CsiIntermediate", [
      [0x00, 0x17, "Anywhere", "Execute"],
      [0x19, 0x19, "Anywhere", "Execute"],
      [0x1c, 0x1f, "Anywhere", "Execute"],
      [0x20, 0x2f, "Anywhere", "Collect"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x30, 0x3f, "CsiIgnore", "Nop"],
      [0x40, 0x7e, "Ground", "CsiDispatch"],
    ]],

    ["DcsEntry", [
      [0x00, 0x17, "Anywhere", "Ignore"],
      [0x19, 0x19, "Anywhere", "Ignore"],
      [0x1c, 0x1f, "Anywhere", "Ignore"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x20, 0x2f, "DcsIntermediate", "Collect"],
      [0x30, 0x39, "DcsParam", "Param"],
      [0x3a, 0x3b, "DcsParam", "Param"],
      [0x3c, 0x3f, "DcsParam", "Collect"],
      [0x40, 0x7e, "DcsPassthrough", "Nop"],
    ]],

    ["DcsIntermediate", [
      [0x00, 0x17, "Anywhere", "Ignore"],
      [0x19, 0x19, "Anywhere", "Ignore"],
      [0x1c, 0x1f, "Anywhere", "Ignore"],
      [0x20, 0x2f, "Anywhere", "Collect"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x30, 0x3f, "DcsIgnore", "Nop"],
      [0x40, 0x7e, "DcsPassthrough", "Nop"],
    ]],

    ["DcsIgnore", [
      [0x00, 0x17, "Anywhere", "Ignore"],
      [0x19, 0x19, "Anywhere", "Ignore"],
      [0x1c, 0x1f, "Anywhere", "Ignore"],
      [0x20, 0x7f, "Anywhere", "Ignore"],
      [0x9c, 0x9c, "Ground", "Nop"],
    ]],

    ["DcsParam", [
      [0x00, 0x17, "Anywhere", "Ignore"],
      [0x19, 0x19, "Anywhere", "Ignore"],
      [0x1c, 0x1f, "Anywhere", "Ignore"],
      [0x30, 0x39, "Anywhere", "Param"],
      [0x3a, 0x3b, "Anywhere", "Param"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x3c, 0x3f, "DcsIgnore", "Nop"],
      [0x20, 0x2f, "DcsIntermediate", "Collect"],
      [0x40, 0x7e, "DcsPassthrough", "Nop"],
    ]],

    ["DcsPassthrough", [
      [0x00, 0x17, "Anywhere", "Put"],
      [0x19, 0x19, "Anywhere", "Put"],
      [0x1c, 0x1f, "Anywhere", "Put"],
      [0x20, 0x7e, "Anywhere", "Put"],
      [0x7f, 0x7f, "Anywhere", "Ignore"],
      [0x9c, 0x9c, "Ground", "Nop"],
    ]],

    ["SosPmApcString", [
      [0x00, 0x17, "Anywhere", "Ignore"],
      [0x19, 0x19, "Anywhere", "Ignore"],
      [0x1c, 0x1f, "Anywhere", "Ignore"],
      [0x20, 0x7f, "Anywhere", "Ignore"],
      [0x9c, 0x9c, "Ground", "Nop"],
    ]],

    ["OscString", [
      [0x00, 0x06, "Anywhere", "Ignore"],
      [0x07, 0x07, "Ground", "Nop"],
      [0x08, 0x17, "Anywhere", "Ignore"],
      [0x19, 0x19, "Anywhere", "Ignore"],
      [0x1c, 0x1f, "Anywhere", "Ignore"],
      [0x20, 0xff, "Anywhere", "OscPut"],
    ]],
  ];

  const state_changes: Uint8Array[] = [];
  for (let i = 0; i < 16; i++) state_changes.push(new Uint8Array(256));
  for (const [from, entries] of spec) {
    for (const [lo, hi, to, action] of entries) {
      for (let byte = lo; byte <= hi; byte++) {
        state_changes[State_discriminant[from]]![byte] = pack(to, action);
      }
    }
  }
  return state_changes;
}

/** `table.rs` text, rebuilt from the verbatim transcription in `table.ts`. */
function table_rs_from_table_ts(): string {
  const src = readFileSync(join(import.meta.dir, "table.ts"), "utf8").split("\n");
  const out: string[] = ["// This file is @generated by crates/anstyle-parse/src/state/codegen.rs", "", "#[rustfmt::skip]"];
  let inside = false;
  for (const line of src) {
    if (line === "export const STATE_CHANGES: readonly Uint8Array[] = [") {
      inside = true;
      out.push("pub(crate) const STATE_CHANGES: [[u8; 256]; 16] = [");
      continue;
    }
    if (!inside || line === "") continue;
    if (line === "  new Uint8Array([") out.push("    [");
    else if (line === "  ]),") out.push("    ],");
    else if (line === "];") out.push("];");
    else {
      const m = /^( *)(.*)$/.exec(line)!;
      const text = m[2]!;
      out.push(" ".repeat(m[1]!.length * 2) + text + (text.startsWith("0x") ? " " : ""));
    }
  }
  return out.join("\n") + "\n";
}
